val selector = Selector.open()
server.configureBlocking(false).register(selector, SelectionKey.OP_ACCEPT)

while (running) {
  selector.select()                                   // one thread blocks here
  val keys = selector.selectedKeys().iterator()
  while (keys.hasNext) {
    val key = keys.next(); keys.remove()              // consume before dispatch
    dispatch(key)                                     // handler for this channel
  }
}
